<?php require_once __DIR__.'/../includes/functions.php';require_role(['admin','finance']);$rows=db()->query("SELECT u.name,u.email,u.created_at,COUNT(o.id) orders FROM users u JOIN customers c ON c.user_id=u.id LEFT JOIN orders o ON o.customer_id=c.id WHERE u.role='customer' GROUP BY u.id ORDER BY u.created_at DESC")->fetchAll();?><!doctype html><html lang="id"><head><?php include __DIR__.'/../includes/head.php';?></head><body><?php include __DIR__.'/../includes/header.php';?><main class="content"><h1>Customers</h1><div class="table-wrap"><table><tr><th>Nama</th><th>Email</th><th>Orders</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['orders'])?></td></tr><?php endforeach;?></table></div></main></body></html>